import test from 'node:test';
import assert from 'node:assert/strict';
import { statement } from '../src/statements.js';
import { createInvoice, issueInvoice } from '../src/invoices.js';
import { recordPayment } from '../src/payments.js';

test('statement returns empty list for customer with no issued invoices', () => {
  const invoices = [];
  const r = statement('C-001', invoices, '2026-10-31');
  assert.equal(r.ok, true);
  assert.equal(r.value.customerId, 'C-001');
  assert.equal(r.value.invoices.length, 0);
  assert.equal(r.value.totalDue, 0);
});

test('statement includes only issued invoices', () => {
  const draft = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-01',
    lines: [{ sku: 'DES-HOUR', qty: 5 }],
  }).value;

  const issued = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-05',
    lines: [{ sku: 'DES-HOUR', qty: 5 }],
  }).value;
  const issuedWithNumber = issueInvoice(issued, []).value;

  const invoices = [draft, issuedWithNumber];
  const r = statement('C-001', invoices, '2026-10-31');
  assert.equal(r.ok, true);
  assert.equal(r.value.invoices.length, 1);
  assert.equal(r.value.invoices[0].number, 'INV-2026-0001');
});

test('statement includes partially_paid invoices', () => {
  const inv = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-01',
    lines: [{ sku: 'DES-HOUR', qty: 5 }],
  }).value;

  const issued = issueInvoice(inv, []).value;
  const withPayment = recordPayment(issued, { amount: 10000, date: '2026-10-15' }).value;

  const invoices = [withPayment];
  const r = statement('C-001', invoices, '2026-10-31');
  assert.equal(r.ok, true);
  assert.equal(r.value.invoices.length, 1);
  assert.equal(r.value.invoices[0].due, 38854); // 48854 - 10000
});

test('statement filters by asOf date', () => {
  const inv1 = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-01',
    lines: [{ sku: 'DES-HOUR', qty: 5 }],
  }).value;
  const issued1 = issueInvoice(inv1, []).value;

  const inv2 = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-15',
    lines: [{ sku: 'DES-HOUR', qty: 5 }],
  }).value;
  const issued2 = issueInvoice(inv2, ['INV-2026-0001']).value;

  const invoices = [issued1, issued2];
  const r = statement('C-001', invoices, '2026-10-10');
  assert.equal(r.ok, true);
  assert.equal(r.value.invoices.length, 1);
  assert.equal(r.value.invoices[0].issueDate, '2026-10-01');
});

test('statement includes invoices issued on asOf date', () => {
  const inv = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-15',
    lines: [{ sku: 'DES-HOUR', qty: 5 }],
  }).value;
  const issued = issueInvoice(inv, []).value;

  const invoices = [issued];
  const r = statement('C-001', invoices, '2026-10-15');
  assert.equal(r.ok, true);
  assert.equal(r.value.invoices.length, 1);
});

test('statement excludes invoices after asOf date', () => {
  const inv = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-16',
    lines: [{ sku: 'DES-HOUR', qty: 5 }],
  }).value;
  const issued = issueInvoice(inv, []).value;

  const invoices = [issued];
  const r = statement('C-001', invoices, '2026-10-15');
  assert.equal(r.ok, true);
  assert.equal(r.value.invoices.length, 0);
});

test('statement excludes paid invoices', () => {
  const inv = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-01',
    lines: [{ sku: 'DES-HOUR', qty: 5 }],
  }).value;

  const issued = issueInvoice(inv, []).value;
  const paid = recordPayment(issued, { amount: 48854, date: '2026-10-15' }).value;

  const invoices = [paid];
  const r = statement('C-001', invoices, '2026-10-31');
  assert.equal(r.ok, true);
  assert.equal(r.value.invoices.length, 0);
});

test('statement filters by customer id', () => {
  const inv1 = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-01',
    lines: [{ sku: 'DES-HOUR', qty: 5 }],
  }).value;
  const issued1 = issueInvoice(inv1, []).value;

  const inv2 = createInvoice({
    customerId: 'C-002',
    issueDate: '2026-10-01',
    lines: [{ sku: 'DES-HOUR', qty: 5 }],
  }).value;
  const issued2 = issueInvoice(inv2, ['INV-2026-0001']).value;

  const invoices = [issued1, issued2];
  const r = statement('C-001', invoices, '2026-10-31');
  assert.equal(r.ok, true);
  assert.equal(r.value.invoices.length, 1);
  assert.equal(r.value.invoices[0].number, 'INV-2026-0001');
});

test('statement calculates due amounts correctly', () => {
  const inv = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-01',
    lines: [{ sku: 'DES-HOUR', qty: 5 }],
  }).value;

  const issued = issueInvoice(inv, []).value;

  const invoices = [issued];
  const r = statement('C-001', invoices, '2026-10-31');
  assert.equal(r.ok, true);
  assert.equal(r.value.invoices[0].due, 48854); // Full amount due
  assert.equal(r.value.invoices[0].total, 48854);
});

test('statement calculates due correctly for partially paid invoice', () => {
  const inv = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-01',
    lines: [{ sku: 'DES-HOUR', qty: 5 }],
  }).value;

  const issued = issueInvoice(inv, []).value;
  const partial1 = recordPayment(issued, { amount: 20000, date: '2026-10-10' }).value;
  const partial2 = recordPayment(partial1, { amount: 15000, date: '2026-10-15' }).value;

  const invoices = [partial2];
  const r = statement('C-001', invoices, '2026-10-31');
  assert.equal(r.ok, true);
  assert.equal(r.value.invoices[0].due, 13854); // 48854 - 20000 - 15000
  assert.equal(r.value.invoices[0].total, 48854);
});

test('statement sorts invoices by issueDate', () => {
  const inv3 = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-15',
    lines: [{ sku: 'DES-HOUR', qty: 2 }],
  }).value;
  const issued3 = issueInvoice(inv3, []).value;

  const inv1 = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-01',
    lines: [{ sku: 'DES-HOUR', qty: 5 }],
  }).value;
  const issued1 = issueInvoice(inv1, ['INV-2026-0001']).value;

  const inv2 = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-10',
    lines: [{ sku: 'DES-HOUR', qty: 3 }],
  }).value;
  const issued2 = issueInvoice(inv2, ['INV-2026-0001', 'INV-2026-0002']).value;

  const invoices = [issued3, issued1, issued2];
  const r = statement('C-001', invoices, '2026-10-31');
  assert.equal(r.ok, true);
  assert.equal(r.value.invoices.length, 3);
  assert.equal(r.value.invoices[0].issueDate, '2026-10-01');
  assert.equal(r.value.invoices[1].issueDate, '2026-10-10');
  assert.equal(r.value.invoices[2].issueDate, '2026-10-15');
});

test('statement calculates totalDue', () => {
  const inv1 = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-01',
    lines: [{ sku: 'DES-HOUR', qty: 5 }],
  }).value;
  const issued1 = issueInvoice(inv1, []).value;

  const inv2 = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-10',
    lines: [{ sku: 'DES-HOUR', qty: 3 }],
  }).value;
  const issued2 = issueInvoice(inv2, ['INV-2026-0001']).value;

  const invoices = [issued1, issued2];
  const r = statement('C-001', invoices, '2026-10-31');
  assert.equal(r.ok, true);
  // Both invoices are for gold tier customer (5% discount)
  // inv1: 42500 - 2125 + 8479 = 48854
  // inv2: 25500 - 1275 + 5108 = 29333
  // total: 78187
  assert.equal(r.value.totalDue, 78187);
});

test('statement calculates totalDue with partial payments', () => {
  const inv1 = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-01',
    lines: [{ sku: 'DES-HOUR', qty: 5 }],
  }).value;
  const issued1 = issueInvoice(inv1, []).value;
  const paid1 = recordPayment(issued1, { amount: 20000, date: '2026-10-15' }).value;

  const inv2 = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-10',
    lines: [{ sku: 'DES-HOUR', qty: 3 }],
  }).value;
  const issued2 = issueInvoice(inv2, ['INV-2026-0001']).value;
  const paid2 = recordPayment(issued2, { amount: 10000, date: '2026-10-20' }).value;

  const invoices = [paid1, paid2];
  const r = statement('C-001', invoices, '2026-10-31');
  assert.equal(r.ok, true);
  // inv1 due: 48854 - 20000 = 28854
  // inv2 due: 29333 - 10000 = 19333
  // total due: 48187
  assert.equal(r.value.totalDue, 48187);
});

test('statement includes issueDate, dueDate, and total in invoice records', () => {
  const inv = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-01',
    lines: [{ sku: 'DES-HOUR', qty: 5 }],
    terms: 'NET14',
  }).value;
  const issued = issueInvoice(inv, []).value;

  const invoices = [issued];
  const r = statement('C-001', invoices, '2026-10-31');
  assert.equal(r.ok, true);
  const inv_stmt = r.value.invoices[0];
  assert.equal(inv_stmt.number, 'INV-2026-0001');
  assert.equal(inv_stmt.issueDate, '2026-10-01');
  assert.equal(inv_stmt.dueDate, '2026-10-15');
  assert.equal(inv_stmt.total, 48854);
  assert.equal(inv_stmt.due, 48854);
});

test('statement reports CUSTOMER_NOT_FOUND for unknown customer', () => {
  const invoices = [];
  const r = statement('C-999', invoices, '2026-10-31');
  assert.deepEqual(r, { ok: false, error: 'CUSTOMER_NOT_FOUND' });
});

test('statement works with multiple customers in invoice list', () => {
  const inv1 = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-01',
    lines: [{ sku: 'DES-HOUR', qty: 5 }],
  }).value;
  const issued1 = issueInvoice(inv1, []).value;

