    customerId: 'C-003',
    issueDate: '2026-10-01',
    lines: [
      { sku: 'DES-HOUR', qty: 5 },
      { sku: 'DEV-HOUR', qty: 3 },
    ],
  }).value;

  const { applyVoucher } = await import('../src/invoices.js');
  const withVoucher = applyVoucher(inv, { code: 'PROMO', amount: 5000 }).value;
  const issued = issueInvoice(withVoucher, []).value;
  const paid = recordPayment(issued, { amount: 30000, date: '2026-10-15' }).value;

  const invoices = [paid];
  const r = statement('C-003', invoices, '2026-10-31');
  assert.equal(r.ok, true);
  // C-003 is silver tier (2.5% discount)
  // 42500 + 28500 = 71000, discount = 1775 + 712.5 = 2487.5, VAT = 14712, voucher = 5000
  // total = 71000 - 2487.5 + 14712 - 5000 = 78224.5
  // due = 78224.5 - 30000 = 48224.5
  const inv_stmt = r.value.invoices[0];
  assert.equal(inv_stmt.total, 78224.5);
  assert.equal(inv_stmt.due, 48224.5);
});

